import { describe, expect, it } from "vitest";
import { TrackerResponseDataSchema } from "./conversation";

const baseTracker = {
  sender_id: "s1",
  events: [{ event: "user", timestamp: 1 }],
  slots: {},
};

describe("TrackerResponseDataSchema stack", () => {
  it("accepts a skill frame without flow_id or step_id", () => {
    const parsed = TrackerResponseDataSchema.parse({
      ...baseTracker,
      stack: [{ frame_id: "f1", type: "skill", skill_id: "travel_notice" }],
    });

    expect(parsed.stack).toHaveLength(1);
    expect(parsed.stack[0]?.flow_id).toBeUndefined();
    expect(parsed.stack[0]?.step_id).toBeUndefined();
    expect(parsed.stack[0]?.type).toBe("skill");
    expect(parsed.stack[0]?.skill_id).toBe("travel_notice");
  });

  it("keeps Mantle frame_type on a pending skill frame", () => {
    const parsed = TrackerResponseDataSchema.parse({
      ...baseTracker,
      stack: [
        {
          frame_id: "f1",
          type: "skill",
          skill_id: "card_replace",
          frame_type: "pending",
        },
      ],
    });

    expect(parsed.stack[0]?.frame_type).toBe("pending");
  });

  it("accepts an ordered-block frame without flow_id", () => {
    const parsed = TrackerResponseDataSchema.parse({
      ...baseTracker,
      stack: [
        {
          frame_id: "f2",
          type: "ordered_block",
          skill_id: "card_replace",
          block_id: "main",
          step_id: "confirm",
        },
      ],
    });

    expect(parsed.stack[0]?.flow_id).toBeUndefined();
    expect(parsed.stack[0]?.block_id).toBe("main");
    expect(parsed.stack[0]?.step_id).toBe("confirm");
  });

  it("still accepts a historical flow frame", () => {
    const parsed = TrackerResponseDataSchema.parse({
      ...baseTracker,
      stack: [{ frame_id: "f3", type: "flow", flow_id: "my_flow", step_id: "s1" }],
    });

    expect(parsed.stack[0]?.flow_id).toBe("my_flow");
    expect(parsed.stack[0]?.step_id).toBe("s1");
  });

  it("rejects a stack frame missing required frame_id", () => {
    expect(() =>
      TrackerResponseDataSchema.parse({
        ...baseTracker,
        stack: [{ type: "skill", skill_id: "card_replace" }],
      }),
    ).toThrow();
  });

  it("rejects a skill frame missing skill_id", () => {
    expect(() =>
      TrackerResponseDataSchema.parse({
        ...baseTracker,
        stack: [{ frame_id: "f4", type: "skill" }],
      }),
    ).toThrow();
  });

  it("rejects an ordered-block frame missing block_id or step_id", () => {
    expect(() =>
      TrackerResponseDataSchema.parse({
        ...baseTracker,
        stack: [{ frame_id: "f5", type: "ordered_block", skill_id: "card_replace" }],
      }),
    ).toThrow();
  });

  it("rejects a flow-like frame missing flow_id or step_id", () => {
    expect(() =>
      TrackerResponseDataSchema.parse({
        ...baseTracker,
        stack: [{ frame_id: "f6", type: "flow" }],
      }),
    ).toThrow();
  });
});
